// СГЕНЕРИРОВАНО (scratchpad/gen/mask.py): маска воды по фонам локаций.
// Сетка 96x54, ключ — stem файла фона (ru_<id>). 1 — вода.
const int kWaterMaskW = 96;
const int kWaterMaskH = 54;

/// Правки масок из админки (оверрайды поверх сид-дефолтов). Заполняется на
/// старте игры из ContentOverrides; пусто — используются сид-маски.
Map<String, String> _waterMaskOverrides = const {};
void setWaterMaskOverrides(Map<String, String> m) => _waterMaskOverrides = m;

/// Вода ли в точке (xN,yN — нормализованы 0..1) на фоне `stem` (`ru_<id>`).
/// Нет маски — считаем водой (не ограничиваем). Оверрайд админки приоритетнее.
bool waterAt(String stem, double xN, double yN) {
  final m = _waterMaskOverrides[stem] ?? kWaterMasks[stem];
  if (m == null) return true;
  final cx = (xN * kWaterMaskW).floor().clamp(0, kWaterMaskW - 1);
  final cy = (yN * kWaterMaskH).floor().clamp(0, kWaterMaskH - 1);
  return m[cy * kWaterMaskW + cx] == '1';
}

const Map<String, String> kWaterMasks = {
  'ru_baikal':
      '',
  'ru_ladoga':
      '',
  'ru_akhtuba':
      '',
  'ru_amur':
      '',
  'ru_don':
      '',
  'ru_kamchatka':
      '',
  'ru_rybinsk':
      '',
  'ru_seliger':
      '',
  'ru_yenisei':
      '',
};
